mobile-android-chips--assist.snippet:
import { Component } from '@angular/core';
import { AndroidChipComponent } from './android-chip.component';

@Component({
  selector: 'app-demo',
  imports: [AndroidChipComponent],
  template: `
    <div class="p-4">
        <app-android-chip
            [kind]="kind"
            [label]="label"
            [icon]="icon"
            [(selected)]="selected" />
    </div>`,
})
export class DemoComponent {
  kind = 'assist';
  label = 'Assist';
  selected = false;
  selectedChange(event: unknown) {}
}

